ansparams: ptoAns+t*vecAns;
anseqParam1: x=ansparams[1];
anseqParam2: y=ansparams[2];
anseqParam3: z=ansparams[3];
anseqImpl1: eliminate([anseqParam1, anseqParam2],[t])[1]=0;
anseqImpl2: eliminate([anseqParam1, anseqParam3],[t])[1]=0;
