anseqsImpl: unique([anseqImpl1, anseqImpl2, anseqImpl3]);

questionvariables.text:
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: expand(lhs(expr)-rhs(expr))=0,
eq1: lhs(eq)*denom(lhs(eq))=0,
tnoIndep: subst([x=0,y=0,z=0], lhs(eq1)),
coefs: [coeff(lhs(eq1),x), coeff(lhs(eq1),y), coeff(lhs(eq1),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq1)/divisor=rhs(eq1)/divisor),
return (ecSimplificada)
);

vecPlano: [rand_with_prohib(1,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
ecPlano: vecPlano.[x,y,z]+rand_with_prohib(-3,3,[0])=0;
ecPlano: simplifica_ec(ecPlano);

ptoP: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];

/*Valores PAU
ecPlano: 2*x+y+2*z=8;
vecPlano: [2,1,2];
ptoP: [10,0,10];*/


/*Comprobación de que punto no pertenece a plano*/
chkPtoNoEnPlano(pto, plano):=not is(subst([x=pto[1], y=pto[2], z=pto[3]],plano));

chkPtoPNoEnPlano: chkPtoNoEnPlano(ptoP,ecPlano);

/*Distancia punto-plano*/
distPtoPlano(pto,plano):=block(
    plano: lhs(plano)-rhs(plano)=rhs(plano)-rhs(plano),
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);

tans1: distPtoPlano(ptoP, ecPlano);

/*Intersección del plano con los ejes de coordenadas*/
intEjex: solve(subst([y=0,z=0], ecPlano));
intEjey: solve(subst([x=0,z=0], ecPlano));
intEjez: solve(subst([x=0,y=0], ecPlano));

ptoA: [rhs(intEjex[1]), 0, 0]; tans2: ptoA[1];
ptoB: [0, rhs(intEjey[1]), 0]; tans3: ptoB[2];
ptoC: [0, 0, rhs(intEjez[1])]; tans4: ptoC[3];

/*Área del triángulo ptoA-ptoB-ptoC*/
areaTriangulo(ptoA, ptoB, ptoC):=block(
    vecAB: ptoB-ptoA,
    vecAC: ptoC-ptoA,
    prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]],
    productoVectorial: prodVect(vecAB, vecAC),
    moduloProdVect: sqrt(productoVectorial.productoVectorial),
    areaT: moduloProdVect/2,
    return(areaT)
);

tans5: areaTriangulo(ptoA, ptoB, ptoC);

/*Volumen tetraedro vectores vecA-vecB-vecC*/
volumenTetraedroVecs(vecA, vecB, vecC):=block(
    prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]],
    productoVectorial: prodVect(vecB, vecC),
    prodMixto: vecA.productoVectorial,
    volumen: abs(prodMixto)/6,
    return(volumen)
);

/*Volumen tetraedro cuatro puntos*/
volumenTetraedroPtos(ptoP, ptoA, ptoB, ptoC):=block(
    prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]],
    vecA: ptoP-ptoA,
    vecB: ptoP-ptoB,
    vecC: ptoP-ptoC,
    productoVectorial: prodVect(vecB, vecC),
    prodMixto: vecA.productoVectorial,
    volumen: abs(prodMixto)/6,
    return(volumen)
);

tans6: volumenTetraedroPtos(ptoP, ptoA, ptoB, ptoC);

/*a2 junio 2014*/
/*Funciones*/
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];

/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

/*Posición relativa de dos rectas*/
posRelativaRectas(ptoR, vecR, ptoS, vecS):=block(
paramsR: ptoR+t*vecR,
eqParam1R: x=paramsR[1],
eqParam2R: y=paramsR[2],
eqParam3R: z=paramsR[3],
eqImpl1R: simplifica_ec(eliminate([eqParam1R, eqParam2R],[t])[1]=0),
eqImpl2R: simplifica_ec(eliminate([eqParam1R, eqParam3R],[t])[1]=0),
eqImpl3R: simplifica_ec(eliminate([eqParam2R, eqParam3R],[t])[1]=0),
eqsImplR: unique([eqImpl1R, eqImpl2R, eqImpl3R]),
paramsS: ptoS+t*vecS,
eqParam1S: x=paramsS[1],
eqParam2S: y=paramsS[2],
eqParam3S: z=paramsS[3],
eqImpl1S: simplifica_ec(eliminate([eqParam1S, eqParam2S],[t])[1]=0),
eqImpl2S: simplifica_ec(eliminate([eqParam1S, eqParam3S],[t])[1]=0),
eqImpl3S: simplifica_ec(eliminate([eqParam2S, eqParam3S],[t])[1]=0),
eqsImplS: unique([eqImpl1S, eqImpl2S, eqImpl3S]),
todasLasEcs: join(eqsImplR,eqsImplS),
solSistema: solve(todasLasEcs, [x,y,z]),
seCruzan: false,
sonParalelas: false,
sonSecantes: false,
sonCoincidentes: false,
numParametros: length(listofvars(solSistema))-3,
if numParametros=0 then sonSecantes: true,
if numParametros=1 then sonCoincidentes: true,
if numParametros=-3 then block(
    proporc: solve(vecR-k*vecS, k),
    if length(proporc)>0 then sonParalelas: true,
    if length(proporc)=0 then seCruzan: true
    ),
opciones: [["se cruzan", seCruzan],["son paralelas", sonParalelas], ["son secantes", sonSecantes], ["son coincidentes", sonCoincidentes]],
return(opciones)
);

/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto: simplifica_ec(planoPerpAVectorPorPto),
return(planoPerpAVectorPorPto));

simplifica_vector(vect):= block(
    denomComun: lcm(denom(vect[1]), lcm(denom(vect[2]), denom(vect[3]))),
    nuevoVect: vect*denomComun,
    divisor: gcd(nuevoVect[1], gcd(nuevoVect[2], nuevoVect[3])),
    return(nuevoVect/divisor)
);

/*Distancia entre rectas*/
distRectas(ptoR, vecR, ptoS, vecS):=block(
    matrizProdMixto: matrix(vecR, vecS, ptoS-ptoR),
    productoMixto: determinant(matrizProdMixto),
    productoVectorial: prodVect(vecR, vecS),
    distancia: abs(productoMixto)/(sqrt(productoVectorial.productoVectorial)),
    return(distancia)    
);

/*Función para extraer punto y vector de ecuaciones implícitas de la recta (intersección de dos planos)*/
ptoYVecDeEcsImplicitas(eqsImplicitas):=block(
vecInt:[none, none, none],
ptoInt: [none, none, none],
sols: solve(eqsImplicitas,[x,y,z]),
for i:1 thru 3 do (
sol: sols[1][i],
expr: rhs(sol),
if length(listofvars(expand(expr)))=0 then parametro:0 else parametro:listofvars(expr)[1],
coefi: coeff(expand(expr), parametro),
if parametro=0 then coef:0 else coef: coeff(expand(rhs(sols[1][i])),parametro),
const: subst(parametro = 0, expr),
ptoInt[i]: const,
vecInt[i]: coef
),
return([ptoInt, vecInt])
);

/*Genero ecuaciones de las rectas (deben cruzarse) y del punto A*/
ptoR: [rand_with_step(-3,3,1), rand_with_step(-3,3,1), rand_with_step(-3,3,1)];
vecR: [rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0])];
ptoS: [rand_with_prohib(-3,3,[ptoR[1]]), rand_with_prohib(-3,3,[ptoR[2]]), rand_with_prohib(-3,3,[ptoR[3]])];
vecS: [rand_with_prohib(-3,3,[0,vecR[1]]), rand_with_prohib(-3,3,[0,vecR[2]]), rand_with_prohib(-3,3,[0,vecR[3]])];
ptoA: [rand_with_prohib(-3,3,[ptoR[1], ptoS[1]]), rand_with_prohib(-3,3,[ptoR[2], ptoS[2]]), rand_with_prohib(-3,3,[ptoR[3], ptoS[3]])];

/*Valores PAU
ptoR: [1,0,2];
vecR: [2,3,1];
ptoS: [-1,1,1];
vecS: [-2,3,1];
ptoA: [-1,0,2];*/

paramsR: ptoR+t*vecR;
eqParam1R: x=paramsR[1];
eqParam2R: y=paramsR[2];
eqParam3R: z=paramsR[3];
eqImpl1R: simplifica_ec(eliminate([eqParam1R, eqParam2R],[t])[1]=0);
eqImpl2R: simplifica_ec(eliminate([eqParam1R, eqParam3R],[t])[1]=0);
eqImpl3R: simplifica_ec(eliminate([eqParam2R, eqParam3R],[t])[1]=0);
eqsImplR: unique([eqImpl1R, eqImpl2R, eqImpl3R]);
paramsS: ptoS+t*vecS;
eqParam1S: x=paramsS[1];
eqParam2S: y=paramsS[2];
eqParam3S: z=paramsS[3];
eqImpl1S: simplifica_ec(eliminate([eqParam1S, eqParam2S],[t])[1]=0);
eqImpl2S: simplifica_ec(eliminate([eqParam1S, eqParam3S],[t])[1]=0);
eqImpl3S: simplifica_ec(eliminate([eqParam2S, eqParam3S],[t])[1]=0);
eqsImplS: unique([eqImpl1S, eqImpl2S, eqImpl3S]);

/*Comprobamos su posicion relativa para que se crucen*/
chkPosRel: mcq_correct(posRelativaRectas(ptoR, vecR, ptoS, vecS))[1];

/* Para visualización de ecuación continua de recta
\( \dfrac{ {@x-ptoR[1]@} } { {@vecR[1]@} }= \dfrac{ {@y-ptoR[2]@} } { {@vecR[2]@} } = \dfrac{ {@z-ptoR[3]@}} { {@vecR[3]@} } \)
*/

/*Plano por A y contiene a r*/
