vec1: ptoA-ptoR;
vec2: vecR;
/*Plano dado por punto y dos vectores*/
planoPtoYDosVect(ptoPlano, vec1, vec2):= block(
    matriz: matrix([x,y,z]-ptoPlano, vec1, vec2),
    ecPlano: determinant(matriz)=0,
    ecPlano: simplifica_ec(ecPlano),
    return(ecPlano)
);

planoPi: planoPtoYDosVect(ptoPlano, vec1, vec2);
tans1: planoPi;

/*Plano por A y perpendicular a s*/
planoSigma: planoPerpAVectPorPto(ptoA, vecS);
tans2: planoSigma;

