ptoParalelaAR: [1,0,-1];*/

tans11: ptoParalelaAR[1]; tans21: ptoParalelaAR[2]; tans31: ptoParalelaAR[3]; 

vecParalelaAR: vecR; tans12:vecParalelaAR[1]; tans22:vecParalelaAR[2]; tans32:vecParalelaAR[3]; 

paramsTans: ptoParalelaAR+t*vecParalelaAR;
eqParam1Tans: x=paramsTans[1];
eqParam2Tans: y=paramsTans[2];
eqParam3Tans: z=paramsTans[3];
eqImpl1Tans: simplifica_ec(eliminate([eqParam1Tans, eqParam2Tans],[t])[1]=0);
eqImpl2Tans: simplifica_ec(eliminate([eqParam1Tans, eqParam3Tans],[t])[1]=0);
eqImpl3Tans: simplifica_ec(eliminate([eqParam2Tans, eqParam3Tans],[t])[1]=0);
tanseqsImpl: unique([eqImpl1Tans, eqImpl2Tans, eqImpl3Tans]);

/*Apdo b) Plano que contiene a r y es paralelo a s*/
vecPlano: prodVect(vecR, vecS);
ptoPlano: ptoR;
/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
eqPlano: planoPerpAVectPorPto(ptoPlano, vecPlano);
eqPlano: simplifica_ec(eqPlano);
tans3: eqPlano;

/*Distancia entre rectas r y s*/
/*Será la distancia de s al plano del apartado b)*/
/*Distancia punto-plano*/
distPtoPlano(pto,plano):=block(
    plano: lhs(plano)-rhs(plano)=rhs(plano)-rhs(plano),
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);
distRS: distPtoPlano(ptoS, eqPlano);
/*Que también podemos calcular con el producto mixto*/
distRectas(ptoR, vecR, ptoS, vecS):=block(
    matrizProdMixto: matrix(vecR, vecS, ptoS-ptoR),
    productoMixto: determinant(matrizProdMixto),
    productoVectorial: prodVect(vecR, vecS),
    distancia: abs(productoMixto)/(sqrt(productoVectorial.productoVectorial)),
    return(distancia)    
);
distRS2: distRectas(ptoR, vecR, ptoS, vecS);
tans4: distRS;

