questionvariables.text:
/*A2Junio2017*/

/*Funciones útiles*/
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],

mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),

divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);


ptoP: [rand_with_step(-2,2,1),rand_with_step(-2,2,1),rand_with_step(-2,2,1)];
ptoR: [rand_with_step(-2,2,1),rand_with_step(-2,2,1),rand_with_step(-2,2,1)];
vecR: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_prohib(-3,3,[0])];

/*Valores PAU
ptoP: [1,1,1];*/

params: ptoR+t*vecR;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
eqImpl2: eliminate([eqParam1, eqParam3],[t])[1]=0;
eqImpl3: eliminate([eqParam2, eqParam3],[t])[1]=0;
eqImpl1: simplifica_ec(eqImpl1);
eqImpl2: simplifica_ec(eqImpl2);
eqImpl3: simplifica_ec(eqImpl3);

/*Valores PAU
eqImpl1: x+y-z+1=0;
eqImpl2: x+2*y-z-1=0;*/

eqsImpl: unique([eqImpl1, eqImpl2, eqImpl3]);

vecAleat: [rand_with_prohib(-3,3,[vecR[1]]),rand_with_prohib(-3,3,[vecR[2]]), rand_with_prohib(-3,3,[vecR[3]])];
ptoPlanoPi: ptoP+vecAleat*rand_with_step(1,2,1);
vecPlanoPi: vecAleat;
/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
ecPlanoPi: planoPerpAVectPorPto(ptoPlanoPi, vecPlanoPi);
ecPlanoPi: simplifica_ec(ecPlanoPi);

/*Valores PAU
ecPlanoPi: x+y+z-1=0;*/

/*Resuelvo apdo a): plano contiene a P y a recta R*/
/*Extraigo punto de recta y vector de recta de ecuaciones implícitas*/
/*Función para extraer punto y vector de ecuaciones implícitas de la recta (intersección de dos planos)*/
vecYPtoDeEcsImplicitas(eqsImplicitas):=block(
vecInt:[none, none, none],
ptoInt: [none, none, none],
sols: solve(eqsImplicitas,[x,y,z]),
for i:1 thru 3 do (
sol: sols[1][i],
expr: rhs(sol),
if length(listofvars(expand(expr)))=0 then parametro:0 else parametro:listofvars(expr)[1],
coefi: coeff(expand(expr), parametro),
coef: coeff(expand(rhs(sols[1][i])),parametro),
const: subst(parametro = 0, expr),
ptoInt[i]: const,
vecInt[i]: coef
),
return([ptoInt, vecInt])
);
ptoYVectR: vecYPtoDeEcsImplicitas([eqImpl1,eqImpl2]);
ptoRCalc: ptoYVectR[1];
vecRCalc: ptoYVectR[2];
ecPlanoApdoA1: radcan(determinant(matrix([x,y,z]-ptoP, ptoP-ptoRCalc, vecRCalc))=0);
ecPlanoApdoA1:simplifica_ec(ecPlanoApdoA1);

tans1: ecPlanoApdoA1;

/*Apdo b) recta por P y perpendicular a pi*/
/*Recta s por P y perpendicular a pi*/
ptoS: ptoP; tans11: ptoS[1]; tans21: ptoS[2]; tans31: ptoS[3];
/*Obtener coeficientes de la ecuación de un plano*/
ecPlanoPi: lhs(ecPlanoPi)-rhs(ecPlanoPi)=0;
coefsPlanoPi: [coeff(lhs(ecPlanoPi),x), coeff(lhs(ecPlanoPi),y), coeff(lhs(ecPlanoPi),z)];
vecS: coefsPlanoPi; tans12: vecS[1]; tans22: vecS[2]; tans32: vecS[3];
paramsS: ptoS+t*vecS;
eqParam1S: x=paramsS[1];
eqParam2S: y=paramsS[2];
eqParam3S: z=paramsS[3];
eqImpl1S: eliminate([eqParam1S, eqParam2S],[t])[1]=0;
eqImpl2S: eliminate([eqParam1S, eqParam3S],[t])[1]=0;
eqImpl3S: eliminate([eqParam2S, eqParam3S],[t])[1]=0;
eqImpl1S: simplifica_ec(eqImpl1S);
eqImpl2S: simplifica_ec(eqImpl2S);
eqImpl3S: simplifica_ec(eqImpl3S);
eqsImplS: unique([eqImpl1S, eqImpl2S, eqImpl3S]);
tanseqsImpl: eqsImplS;

/*Intersección s con planoPi*/
/*Punto de intersección entre recta y plano, dado ptoR, vecR y eqPlano*/
ptoIntRectaPlano(ptoR, vecR, eqPlano):= block(
    eqParam1: x=ptoR[1]+t*vecR[1],
    eqParam2: y=ptoR[2]+t*vecR[2],
    eqParam3: z=ptoR[3]+t*vecR[3],
    sols: solve([eqParam1, eqParam2, eqParam3, eqPlano], [x,y,z,t]),
    ptoInt: [rhs(sols[1][1]), rhs(sols[1][2]), rhs(sols[1][3])],
    return(ptoInt)
);
ptoIntSPi: ptoIntRectaPlano(ptoS, vecS, ecPlanoPi);
tans41: ptoIntSPi[1]; tans42: ptoIntSPi[2]; tans43: ptoIntSPi[3];  

/*Distancia P-Pi: será el módulo del vector P-PtoInt*/
vecPPtoInt: ptoIntSPi-ptoP;
distPPi1: sqrt(vecPPtoInt.vecPPtoInt);
/*O también la distancia punto plano a pinrel*/
/*Distancia punto-plano*/
distPtoPlano(pto,plano):=block(
    plano: lhs(plano)-rhs(plano)=rhs(plano)-rhs(plano),
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);
distPPi2: distPtoPlano(ptoP, ecPlanoPi);
tans5: distPPi2;
/*Malo sería que no coincidieran las dos*/

/*Apdo c) planoSigma contiene a r y es perpendicular a planoPi*/
ptoPlanoSigma: ptoRCalc;
vec1PlanoSigma: vecRCalc;
vec2PlanoSigma: coefsPlanoPi;
ecPlanoSigma: radcan(determinant(matrix([x,y,z]-ptoPlanoSigma, vec1PlanoSigma, vec2PlanoSigma))=0);
ecPlanoSigma: simplifica_ec(ecPlanoSigma);
tans6: ecPlanoSigma;

