questionvariables.text:
/*A2 julio 2018*/
/*Funciones útiles*/
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],

mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),

divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];

/*Área del triángulo ptoA-ptoB-ptoC*/
areaTriangulo(ptoA, ptoB, ptoC):=block(
    vecAB: ptoB-ptoA,
    vecAC: ptoC-ptoA,
    prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]],
    productoVectorial: prodVect(vecAB, vecAC),
    moduloProdVect: sqrt(productoVectorial.productoVectorial),
    areaT: moduloProdVect/2,
    return(areaT)
);


/*Construyo los puntos del enunciado:
A será aleatorio
Genero BA aleatorio
Genero BC como prodVect de BA por un vector aleatorio
B=A+AB
C=A+AC
*/
ptoA: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
vecBA: [rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
vecAleat: [rand_with_prohib(-3,3,[0, vecBA[1]]),rand_with_prohib(-3,3,[0, vecBA[2]]),rand_with_prohib(-3,3,[0, vecBA[3]])];
vecBC: prodVect(vecBA, vecAleat);
ptoB: ptoA - vecBA;
ptoC: vecBC + ptoB;

aleatPtoA: rand([1,2,3]);
ptoAEnunc: copy(ptoA);
ptoAEnunc[aleatPtoA]: k;
ptoAEnunc;

/*Valores PAU
ptoAEnunc: [-1,2,k];
ptoB: [2,3,5];
ptoC: [3,5,3];*/


/*Apdo a: deben ser BA ortogonal a BC*/
vecBA: ptoAEnunc-ptoB;
vecBC: ptoC-ptoB;
eq: vecBA.vecBC=0;
sols: solve(eq,k);
tans1: rhs(first(sols));

/*Apdo B*/
valK: rand_with_prohib(-5,5,[tans1]);
ptoAApdoB: copy(ptoAEnunc);
ptoAApdoB[aleatPtoA]: valK;

/*Valores PAU
ptoAApdoB: [-1,2,6];*/

tans2: areaTriangulo(ptoAApdoB, ptoB, ptoC);

/*Apdo C*/
/*Ecuación del plano que contiene a ptoAApdoB, ptoB y ptoC*/
ptoPlano: ptoAApdoB;
vecP1: ptoB-ptoAApdoB;
vecP2: ptoC-ptoAApdoB;
eqPlanoC: radcan(determinant(matrix([x,y,z]-ptoPlano, vecP1, vecP2))=0);
eqPlanoC: simplifica_ec(eqPlanoC);
tans3: eqPlanoC;

ptoR: [rand_with_step(-2,2,1),rand_with_step(-2,2,1),rand_with_step(-2,2,1)];
vecR: [rand_with_prohib(-2,3,[0]),rand_with_prohib(-2,3,[0]),rand_with_prohib(-2,3,[0])];

/*Valores PAU
ptoR: [-3/2,3/2,0];
vecR: [1,1,2];*/


/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

params: ptoR+t*vecR;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
eqImpl2: eliminate([eqParam1, eqParam3],[t])[1]=0;
eqImpl3: eliminate([eqParam2, eqParam3],[t])[1]=0;
eqImpl1: simplifica_ec(eqImpl1);
eqImpl2: simplifica_ec(eqImpl2);
eqImpl3: simplifica_ec(eqImpl3);
eqsImpl: unique([eqImpl1, eqImpl2, eqImpl3]);

vecS: [rand_with_prohib(-2,3,[0, vecR[1]]),rand_with_prohib(-2,3,[0, vecR[2]]),rand_with_prohib(-2,3,[0, vecR[3]])];
ptoS: ptoR+rand_with_prohib(-2,2,[0])*vecS;

/*Valores PAU no funciona porque r paralela a s y aquí está resuelto haciéndolas secantes
vecS: [1,1,2];
ptoS: [0,-1,2];*/


/*Visualización de ecuación continua de la recta
/( \dfrac{ {@x-ptoS[1]@} } { {@vecS[1]@} }= \dfrac{ {@y-ptoS[2]@} } { {@vecS[2]@} }
        = \dfrac{ {@z-ptoS[3]@}} { {@vecS[3]@} } \)*/

/*Ecuación del plano que contiene a las rectas r y s*/
ptoPlano: ptoR;
vecP1: vecR;
vecP2: vecS;
eqImpl: radcan(determinant(matrix([x,y,z]-ptoPlano, vecP1, vecP2))=0);

tans1: simplifica_ec(eqImpl);

ptoP: [rand_with_step(-2,2,1),rand_with_step(-2,2,1),rand_with_step(-2,2,1)];

/*Valores PAU
ptoP: [0,-1,2];*/

/*Comprobamos que ptoP no está en r*/
/*Distancia punto recta*/
distPR(punto, puntoRecta, vecRecta):=block(
vecPR: punto-puntoRecta,
prodVectorial: prodVect(vecPR,vecRecta),
modProdVect: sqrt(prodVectorial.prodVectorial),
modVecRecta: sqrt(vecRecta.vecRecta),
modProdVect/modVecRecta);
chkTrueOk: is(distPR(ptoP, ptoR, vecR)#0);

/*Recta que pasa por pto P y corta perpendicularmente a r*/
/*Plano que pasa por pto P y es perpendicular a r*/
/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
eqPlano: planoPerpAVectPorPto(ptoP, vecR);
eqPlano: simplifica_ec(eqPlano);
/*Intersección del plano con la recta r*/
ptoIntRyPlanoPerp: solve([eqsImpl[1], eqsImpl[2], eqPlano]);
ptoInt: [rhs(first(ptoIntRyPlanoPerp[1])), rhs(second(ptoIntRyPlanoPerp[1])), rhs(third(ptoIntRyPlanoPerp[1]))];
vecTans: ptoInt-ptoP;
multipl: last(sort([denom(vecTans[1]), denom(vecTans[1]), denom(vecTans[1])]));
vecTans: vecTans*multipl; tans12: vecTans[1]; tans22: vecTans[2]; tans32: vecTans[3];
ptoTans: ptoP; tans11: ptoP[1]; tans21: ptoP[2]; tans31: ptoP[3];
Tansparams: ptoTans+t*vecTans;
TanseqParam1: x=Tansparams[1];
TanseqParam2: y=Tansparams[2];
TanseqParam3: z=Tansparams[3];
TanseqImpl1: eliminate([TanseqParam1, TanseqParam2],[t])[1]=0;
TanseqImpl2: eliminate([TanseqParam1, TanseqParam3],[t])[1]=0;
TanseqImpl3: eliminate([TanseqParam2, TanseqParam3],[t])[1]=0;
TanseqImpl1: simplifica_ec(TanseqImpl1);
TanseqImpl2: simplifica_ec(TanseqImpl2);
TanseqImpl3: simplifica_ec(TanseqImpl3);
TanseqsImpl: unique([TanseqImpl1, TanseqImpl2, TanseqImpl3]);


/*Plano pi apdo c): plano que contiene a s*/
/*Plano por punto S y vecS y vec2*/
vec2: [rand_with_prohib(-3,3,[0,vecS[1]]), rand_with_prohib(-3,3,[0,vecS[2]]), rand_with_prohib(-3,3,[0,vecS[3]])];
ecPlanoApdoC: radcan(determinant(matrix([x,y,z]-ptoS,vecS,vec2)))=0;
ecPlanoApdoC: simplifica_ec(ecPlanoApdoC);
aleatCoef: rand([1,2,3]);
coefsPlano: [coeff(lhs(ecPlanoApdoC),x), coeff(lhs(ecPlanoApdoC),y), coeff(lhs(ecPlanoApdoC),z), subst([x=0, y=0, z=0],lhs(ecPlanoApdoC))];
coefsPlanoEnunc: copy(coefsPlano);
coefsPlanoEnunc[aleatCoef]: a;
coefsPlanoEnunc[4]: b;
ecPlanoApdoCEnunc: coefsPlanoEnunc.[x,y,z,1]=0;

/*Valores PAU
ecPlanoApdoCEnunc: x-2*y+a*z=b;
coefsPlanoEnunc: [1, -2, a, -b];*/

/*Ahora resolvemos dada la ecuación del plano con los parámetros*/
/*Recta en plano si vector recta perpendicular a vector plano y un punto de la recta está en el plano*/
vecPlanoApdoC: [coefsPlanoEnunc[1],coefsPlanoEnunc[2],coefsPlanoEnunc[3]];
prodEsc: vecS.vecPlanoApdoC=0;
ptoEnPlano: subst([x=ptoS[1], y=ptoS[2], z=ptoS[3]], ecPlanoApdoCEnunc);
sols: solve([prodEsc, ptoEnPlano], [a,b]);
valA: rhs(sols[1][1]); tans3: valA;
valB: rhs(sols[1][2]); tans4: valB;

