eqsImplR: unique([eqImpl1R, eqImpl2R, eqImpl3R]),
paramsS: ptoS+t*vecS,
eqParam1S: x=paramsS[1],
eqParam2S: y=paramsS[2],
eqParam3S: z=paramsS[3],
eqImpl1S: simplifica_ec(eliminate([eqParam1S, eqParam2S],[t])[1]=0),
