eqImpl3R: simplifica_ec(eliminate([eqParam2R, eqParam3R],[t])[1]=0);

/*Valores PAU
eqImpl1R: x-y=0;
eqImpl2R: z=10;
rectaR: ptoYVecDeEcsImplicitas([eqImpl1R, eqImpl2R]);
ptoR: rectaR[1];
vecR: rectaR[2];*/


eqsImplR: unique([eqImpl1R, eqImpl2R, eqImpl3R]);
paramsS: ptoS+t*vecS;
eqParam1S: x=paramsS[1];
