eqImpl3S: simplifica_ec(eliminate([eqParam2S, eqParam3S],[t])[1]=0);

/*Valores PAU
eqImpl1S: x+y=8;
eqImpl2S: x+y+z=13;
rectaS: ptoYVecDeEcsImplicitas([eqImpl1S, eqImpl2S]);
ptoS: rectaS[1];
vecS: rectaS[2];*/

eqsImplS: unique([eqImpl1S, eqImpl2S, eqImpl3S]);

/*Comprobamos su posicion relativa para que se crucen*/
chkOkSeCruzan: mcq_correct(posRelativaRectas(ptoR, vecR, ptoS, vecS))[1];

/*Vectores directores de las rectas*/
tans1: vecR;
tans1x: vecR[1]; tans1y: vecR[2]; tans1z: vecR[3];

tans2: vecS;
tans2x: vecS[1]; tans2y: vecS[2]; tans2z: vecS[3];

/*Posición relativa*/
tans3: posRelativaRectas(ptoR, vecR, ptoS, vecS);

/*Plano que contiene a s y es paralelo a r*/
vecPlano: prodVect(vecR, vecS);
eqPlano: planoPerpAVectPorPto(ptoS, vecPlano);
eqPlano: simplifica_ec(eqPlano);
tans4: eqPlano;

/*Distancia entre las rectas r y s*/
