    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

/*Plano dado punto y dos vectores*/
planoPtoYDosVect(ptoPlano, vec1, vec2):= block(
    matriz: matrix([x,y,z]-ptoPlano, vec1, vec2),
    ecPlano: determinant(matriz)=0,
    ecPlano: simplifica_ec(ecPlano),
    return(ecPlano)
);

/*Posición relativa de dos planos*/
posRelativaPlanos(eqPlano1, eqPlano2):= block(
    aa: solve([eqPlano1, eqPlano2], [x,y,z]),
    sonParalelos: false,
    sonSecantes: false,
    sonCoincidentes: false,
    numParametros: length(listofvars(aa))-3,
    if numParametros=-3 then sonParalelos: true,
    if numParametros=1 then sonSecantes: true,
    if numParametros=2 then sonCoincidentes: true,
    opciones: [["son paralelos", sonParalelos], ["son secantes", sonSecantes], ["son coincidentes", sonCoincidentes]],
    return(opciones)
);

/*Obtener coeficientes de la ecuación de un plano=> coefsPlano.[x,y,z,1]=0*/
coefsPlano(ecPlano):=block(
ecPlano: lhs(ecPlano)-rhs(ecPlano)=0,
coefsPlano: [coeff(lhs(ecPlano),x), coeff(lhs(ecPlano),y), coeff(lhs(ecPlano),z), subst([x=0, y=0, z=0],lhs(ecPlano))],
return(coefsPlano)
);

/*Función para extraer punto y vector de ecuaciones implícitas de la recta (intersección de dos planos)*/
ptoYVecDeEcsImplicitas(eqsImplicitas):=block(
vecInt:[none, none, none],
ptoInt: [none, none, none],
sols: solve(eqsImplicitas,[x,y,z]),
for i:1 thru 3 do (
sol: sols[1][i],
expr: rhs(sol),
if length(listofvars(expand(expr)))=0 then parametro:0 else parametro:listofvars(expr)[1],
coefi: coeff(expand(expr), parametro),
if parametro=0 then coef:0 else coef: coeff(expand(rhs(sols[1][i])),parametro),
const: subst(parametro = 0, expr),
ptoInt[i]: const,
vecInt[i]: coef
),
return([ptoInt, vecInt])
);

simplifica_vector(vect):= block(
    denomComun: lcm(denom(vect[1]), lcm(denom(vect[2]), denom(vect[3]))),
    nuevoVect: vect*denomComun,
    divisor: gcd(nuevoVect[1], gcd(nuevoVect[2], nuevoVect[3])),
    return(nuevoVect/divisor)
);

/*Genero puntos del enunciado*/
ptoA: [rand_with_step(-3,3,1), rand_with_step(-3,3,1), rand_with_step(-3,3,1)];
