);

prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];

/*Genero recta r aleatoria, un vector perpendicular a ella y pto A a partir de un punto de la recta y del vector perpendicular*/
ptoR: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
vecR: [rand_with_prohib(-2,3,[0]),rand_with_prohib(-2,3,[0]),rand_with_prohib(-2,3,[0])];

/*Valores PAU
ptoR: [3,-1,0];
vecR: [-1,3,2];*/

params: ptoR+t*vecR;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
