/*Visualización de ecuación continua de la recta  
/( \dfrac{ {@x-ptoR[1]@} } { {@vecR[1]@} }= \dfrac{ {@y-ptoR[2]@} } { {@vecR[2]@} }
        = \dfrac{ {@z-ptoR[3]@}} { {@vecR[3]@} } \)
*/
vecAleat: [rand_with_prohib(-2,3,[0,vecR[1]]),rand_with_prohib(-2,3,[vecR[2]]),rand_with_prohib(-2,3,[0,vecR[3]])];
vecPerpR: prodVect(vecR,vecAleat);
ptoA: ptoR+rand_with_prohib(-2,2,[0])*vecR+rand_with_prohib(2,2,[0])*vecPerpR;


/*Valores PAU
ptoA: [5,7,3];*/


/*Ahora resuelvo el apartado a) a partir de los datos generados*/
/*Plano que pasa por A y es perpendicular a r*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
eqPlano: planoPerpAVectPorPto(ptoA, vecR);
eqPlano: simplifica_ec(eqPlano);
/*Intersección del plano con la recta r*/
interseccion: solve([eqsImpl[1], eqsImpl[2], eqsImpl[3], eqPlano], [x,y,z]);
ptoInt: [rhs(interseccion[1][1]), rhs(interseccion[1][2]), rhs(interseccion[1][3])];
ptoTAns: ptoA; tans11: ptoTAns[1]; tans21: ptoTAns[2]; tans31: ptoTAns[3];
vecTAns: ptoInt-ptoA; tans12: vecTAns[1]; tans22: vecTAns[2]; tans32: vecTAns[3];
tansparams: ptoA+t*vecTAns;
