tanseqImpl2: eliminate([tanseqParam1, tanseqParam3],[t])[1]=0;
tanseqImpl3: eliminate([tanseqParam2, tanseqParam3],[t])[1]=0;
tanseqsImpl:[tanseqImpl1, tanseqImpl2, tanseqImpl3];

/*Apdo b) Distancia A - r*/
/*Distancia punto recta*/
distPR(punto, puntoRecta, vecRecta):=block(
vecPR: punto-puntoRecta,
prodVectorial: prodVect(vecPR,vecRecta),
modProdVect: sqrt(prodVectorial.prodVectorial),
modVecRecta: sqrt(vecRecta.vecRecta),
modProdVect/modVecRecta);
tans3: distPR(ptoA, ptoR, vecR);

/*Apdo c) */
ptoB: [rand_with_prohib(-3,3,[ptoR[1], ptoA[1]]),rand_with_prohib(-3,3,[ptoR[2], ptoA[2]]),rand_with_prohib(-3,3,[ptoR[3], ptoA[3]])];
ptoPi: [rand_with_prohib(-3,3,[ptoB[1], ptoR[1], ptoA[1]]),rand_with_prohib(-3,3,[ptoB[2], ptoR[2], ptoA[2]]),rand_with_prohib(-3,3,[ptoB[3], ptoR[3], ptoA[3]])];

/*Valores PAU
ptoB: [1,1,1];
ptoPi: [3,-1,0];*/

planoPi: planoPerpAVectPorPto(ptoPi, vecR);
/*Distancia punto-plano*/
distPtoPlano(pto,plano):=block(
    plano: lhs(plano)-rhs(plano)=rhs(plano)-rhs(plano),
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);
tans4: distPtoPlano(ptoB, planoPi);

