/* Función para generar planos a una distancia dada de un plano original */
generar_planos(plano, distancia) := block(
    [a, b, c, d, planos],
    /* Extraer los coeficientes del plano original ax + by + cz + d = 0 */
    [a, b, c, d] : plano,
    /* Calcular los nuevos términos independientes para los planos paralelos */
    d1 : d + distancia * sqrt(a^2 + b^2 + c^2),
    d2 : d - distancia * sqrt(a^2 + b^2 + c^2),
    /* Generar las ecuaciones de los planos paralelos */
    planos : [[a, b, c, d1], [a, b, c, d2]],
    return(planos)
);

