chkPNoEnR: is(subst([x=ptoP[1], y=ptoP[2], z=ptoP[3]],eqImpl1) and subst([x=ptoP[1], y=ptoP[2], z=ptoP[3]],eqImpl2));
chkQNoEnR: is(subst([x=ptoQ[1], y=ptoQ[2], z=ptoQ[3]],eqImpl1) and subst([x=ptoQ[1], y=ptoQ[2], z=ptoQ[3]],eqImpl2));
chkTrueOk: not ( chkPNoEnR or chkQNoEnR );

/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
tans2: planoPerpAVectPorPto(ptoP, vector);
tans2: simplifica_ec(tans2);

vecContPlano21: [rand_with_step(-3,3,1), rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
vecContPlano22: vecContPlano21 + [rand_with_prohib(-1,1,[0]), rand_with_prohib(-1,1,[0]), rand_with_prohib(-1,1,[0])];

/*Producto vectorial*/
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];
vecPlano2: prodVect(vecContPlano21,vecContPlano22);

chkNoAlineados: not is (vecPlano2=[0,0,0]);

/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);

ptoPlano1: [rand_with_step(-3,3,1), rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
vecPlano1: vecPlano2 + [0,rand([0,0,1]),rand([0,0,1])];
eqPlano1: planoPerpAVectPorPto(ptoPlano1, vecPlano1);

ptoPlano2: ptoPlano1+[0,rand([0,1]),rand([0,1])];
eqPlano2: planoPerpAVectPorPto(ptoPlano2, vecPlano2);

sonParal: is (not ptoPlano1=ptoPlano2 and vecPlano1=vecPlano2);
sonCoinc: is (eqPlano1=eqPlano2);
sonSecantes: not is (vecPlano1=vecPlano2);

auxtans1: [["paralelos",false], ["coincidentes", false], ["secantes", false]];
auxtans1[1][2]:sonParal;
auxtans1[2][2]:sonCoinc;
auxtans1[3][2]:sonSecantes;
tans1: auxtans1;

ptoPlano2ParaSimetrico: ptoPlano2+rand_with_prohib(-3,3,[0])*vecContPlano21 + rand_with_prohib(-3,3,[0])*vecContPlano22;
ptoP: ptoPlano2ParaSimetrico +rand_with_prohib(-3,3,[0])*vecPlano2;

/*Recta perpendicular a plano2 por P*/
vector: vecPlano2;
ptoRecta: ptoP;
params: ptoRecta+t*vector;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
eqImpl2: eliminate([eqParam1, eqParam3],[t])[1]=0;

/*Intersección plano 2 con recta anterior*/
intersecc: solve([eqImpl1, eqImpl2, eqPlano2],[x,y,z]);
ptoInt: [rhs(intersecc[1][1]), rhs(intersecc[1][2]), rhs(intersecc[1][3])];

/*Simétrico de P respecto de plano 2*/
vecPptoInt: ptoInt-ptoP;
simetrico: ptoP+2*vecPptoInt;
tans2: simetrico;
tans2x: simetrico[1];
tans2y: simetrico[2];
tans2z: simetrico[3];

/*Definición de recta R*/
vecR: [rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0])];
ptoR: ptoPlano1+rand_with_step(1,3,1)*vecR;
params1: ptoR+t*vecR;
eqParam11: x=params1[1];
eqParam21: y=params1[2];
eqParam31: z=params1[3];
eqImpl11: eliminate([eqParam11, eqParam21],[t])[1]=0;
eqImpl21: eliminate([eqParam11, eqParam31],[t])[1]=0;

/*Recta en forma continua*/
xR: (x-ptoR[1])/vecR[1];
yR: (y-ptoR[2])/vecR[2];
zR: (z-ptoR[3])/vecR[3];

auxptoIntRPlano1: solve([eqImpl11, eqImpl21, eqPlano1],[x,y,z]);
ptoIntRPlano1: [rhs(auxptoIntRPlano1[1][1]), rhs(auxptoIntRPlano1[1][2]), rhs(auxptoIntRPlano1[1][3])];
tans3: ptoIntRPlano1;
tans3x: ptoIntRPlano1[1];
tans3y: ptoIntRPlano1[2];
tans3z: ptoIntRPlano1[3];

chkRnoContEnPlano1:not is (vecR.vecPlano1=0);

chk: chkNoAlineados and chkRnoContEnPlano1;

ptoRecta: [rand_with_step(-5,5,1), rand_with_step(-5,5,1), rand_with_step(-5,5,1)];
vector: [rand_with_prohib(-5,5,[0]), rand_with_prohib(-5,5,[0]), rand_with_prohib(-5,5,[0])];
ptoExt: ptoRecta + rand_with_step(1,3,1)*[vector[1]-1,vector[2]+1, vector[3]-1]; 
params: ptoRecta+t*vector;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
eqImpl2: eliminate([eqParam1, eqParam3],[t])[1]=0;
chk1: not is (subst([x=ptoExt[1], y=ptoExt[2], z=ptoExt[3]], eqImpl1) and subst([x=ptoExt[1], y=ptoExt[2], z=ptoExt[3]], eqImpl2));
/*Valores PAU
ptoRecta: [2,6,0];
ptoExt: [0,5,2];
vector: [-1,-2,1];
eqImpl1: 5*x+y+7*z=16;
eqImpl2: 9*x-y+7*z=12;*/
vecPQ: ptoExt-ptoRecta;
tans1x: ptoRecta[1];
tans1y: ptoRecta[2];
tans1z: ptoRecta[3];
tans2x: vecPQ[1];
tans2y: vecPQ[2];
tans2z: vecPQ[3];
cosAngRS: vector.vecPQ/sqrt(vector.vector)/sqrt(vecPQ.vecPQ);
angRS: acos(cosAngRS)/%pi*180;
tans3: float(angRS);
planoPerpARPorP1: vector[1]*x+vector[2]*y+vector[3]*z+DD=0;
aux: solve(subst([x=ptoExt[1], y=ptoExt[2], z=ptoExt[3]],planoPerpARPorP1));
planoPerpARPorP: subst(aux, planoPerpARPorP1);
proyeccPsobreR: solve([eqImpl1, eqImpl2, planoPerpARPorP], [x,y,z]);
tans4x: rhs(proyeccPsobreR[1][1]);
tans4y: rhs(proyeccPsobreR[1][2]);
tans4z: rhs(proyeccPsobreR[1][3]);

