questionvariables.text:
/*p5 julio 2020*/
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: expand(lhs(expr)-rhs(expr))=0,
eq1: lhs(eq)*denom(lhs(eq))=0,
tnoIndep: subst([x=0,y=0,z=0], lhs(eq1)),
coefs: [coeff(lhs(eq1),x), coeff(lhs(eq1),y), coeff(lhs(eq1),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq1)/divisor=rhs(eq1)/divisor),
return (ecSimplificada)
);

vecPlano: [rand_with_prohib(1,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
ecPlano: vecPlano.[x,y,z]+rand_with_prohib(-3,3,[0])=0;
ecPlano: simplifica_ec(ecPlano);

/*Valores PAU
ecPlano: 2*x+y-z-5=0;
vecPlano: [2,1,-1];*/

/*Comprobación de que punto no pertenece a plano*/
chkPtoNoEnPlano(pto, plano):=not is(subst([x=pto[1], y=pto[2], z=pto[3]],plano));

ptoA: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
ptoB: [rand_with_prohib(-3,3,[ptoA[1]]),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];

/*Valores PAU
ptoA: [1,2,-1];
ptoB: [2,1,0];*/

chkPtoANoEnPlano: chkPtoNoEnPlano(ptoA,ecPlano);
chkPtoBNoEnPlano: chkPtoNoEnPlano(ptoB,ecPlano);
chkTrueOk: chkPtoANoEnPlano and chkPtoBNoEnPlano;

/*Plano por A y B perpendicular a ecPlano*/

/*Plano por punto A y con vectores vecPlano y vecAB*/
ptoPlano: ptoB;
vecP1: vecPlano;
vecP2: ptoB-ptoA;
ecPlanoPerpAPiPorAyB: radcan(determinant(matrix([x,y,z]-ptoPlano, vecP1, vecP2))=0);
ecPlanoPerpAPiPorAyB: simplifica_ec(ecPlanoPerpAPiPorAyB);

tans1: ecPlanoPerpAPiPorAyB;

/*Recta por A y perpendicular a plano*/
vecR: vecPlano;
ptoR: ptoA;

params: ptoR+t*vecR;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: eliminate([eqParam1, eqParam2],[t])[1]=0;
eqImpl2: eliminate([eqParam1, eqParam3],[t])[1]=0;
eqImpl3: eliminate([eqParam2, eqParam3],[t])[1]=0;
eqImpl11: simplifica_ec(eqImpl1);
eqImpl21: simplifica_ec(eqImpl2);
eqImpl31: simplifica_ec(eqImpl3);
eqsImpl: unique([eqImpl11,eqImpl21,eqImpl31]);

tans11: ptoR[1]; tans12: vecR[1];
tans21: ptoR[2]; tans22: vecR[2];
tans31: ptoR[3]; tans32: vecR[3];

tans41: eqsImpl[1]; tans42: eqsImpl[2]; 

/*Distancia punto B recta r*/
distPR(punto, puntoRecta, vecRecta):=block(
vecPR: punto-puntoRecta,
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]],
prodVectorial: prodVect(vecPR,vecRecta),
modProdVect: sqrt(prodVectorial.prodVectorial),
modVecRecta: sqrt(vecRecta.vecRecta),
modProdVect/modVecRecta);

tans5: distPR(ptoB, ptoR, vecR);

