/*P5 julio 2021*/
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);
ptoP: [rand_with_step(-3,3,1),rand_with_step(-3,3,1),rand_with_step(-3,3,1)];
vecAleat: [rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0]), rand_with_prohib(-3,3,[0])];
aleat: rand_with_prohib(-2,2,[0]);
if vecAleat=[0,0,0] then vecAleat: [2,4,-1];
ptoQ: ptoP+aleat*vecAleat;
ptoR: ptoP+rand_with_prohib(-2,2,[0, aleat])*vecAleat;
ptoREnunc: [m,ptoR[2],ptoR[3]];
valM: rand_with_prohib(-3,3,[ptoR[1]]);
ptoRab: [valM,ptoR[2],ptoR[3]];
/*Valores con que apareció en PAU
ptoP:[1,1,0];
ptoQ:[2,-1,1];
ptoR:[0,3,-1];
ptoREnunc: [m,ptoR[2],ptoR[3]];
valM:1;
ptoRab: [valM,ptoR[2],ptoR[3]];*/
ecPlano: radcan(determinant(matrix([x,y,z]-ptoP,ptoQ-ptoP,ptoRab-ptoP)))=0;
ecPlano: simplifica_ec(ecPlano);
tans1: ecPlano;
distPtoPlano(pto,plano):=block(
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);
tans2: distPtoPlano([0,0,0], ecPlano);
/*Apartado b: ecuación recta r  que pasa por R con m=valM y es paralela a recta s que pasa por P y Q*/
vecR: ptoQ-ptoP;
tans3p: ptoR;
tans3v: vecR;
ptoTAns: tans3p;
vecTAns: tans3v;
paramsTAns: ptoTAns+t*vecTAns;
eqParamTAns1: x=paramsTAns[1];
eqParamTAns2: y=paramsTAns[2];
eqParamTAns3: z=paramsTAns[3];
eqImpl1TAns: eliminate([eqParamTAns1, eqParamTAns2],[t])[1]=0;
eqImpl2TAns: eliminate([eqParamTAns2, eqParamTAns3],[t])[1]=0;
eqImpl3TAns: eliminate([eqParamTAns1, eqParamTAns3],[t])[1]=0;
eqsImplTAns: unique([eqImpl1TAns, eqImpl2TAns, eqImpl3TAns]);
tans31: simplifica_ec(eqsImplTAns[1]);
tans32: simplifica_ec(eqsImplTAns[2]);

/*Apartado c: Valores de m para los que P, Q y R están alineados*/
tans4: ptoR[1];

/*Recta vectorial que contiene a P,Q y R cuando están alineados*/
/*Será la recta PQ, por ejemplo*/
tans5: ptoP;
tans5x: ptoP[1];
tans5y: ptoP[2];
tans5z: ptoP[3];
vecRecta: ptoQ-ptoP;
tans6: vecRecta;
tans6x: vecRecta[1];
