questionvariables.text:
/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

ptoR: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];
vecR: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];

/*Valores PAU
ptoR: [1,2,0];
vecR: [0,1,2];*/

params: ptoR+t*vecR;
eqParam1: x=params[1];
eqParam2: y=params[2];
eqParam3: z=params[3];
eqImpl1: simplifica_ec(eliminate([eqParam1, eqParam2],[t])[1]=0);
eqImpl2: simplifica_ec(eliminate([eqParam1, eqParam3],[t])[1]=0);
eqImpl3: simplifica_ec(eliminate([eqParam2, eqParam3],[t])[1]=0);
eqsImpl: unique([eqImpl1, eqImpl2, eqImpl3]);

ptoPlano: ptoR;
vecP1: vecR;
vecP2: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];
eqImpl: radcan(determinant(matrix([x,y,z]-ptoPlano, vecP1, vecP2))=0);
eqImpl: simplifica_ec(eqImpl);
coefy: coeff(lhs(eqImpl),y);
chkTrueOk: not is(coefy=0);

eqPlano1: subst(coefy*y=m*y, eqImpl);

eqPlano2: rand_with_prohib(-2,2,[0])*x+m*y+rand_with_prohib(-2,2,[0])*z+rand_with_prohib(-2,2,[0])=0;

/*eqPlano1 dará solución del parámetro y eqPlano2 generalmente no dará solución*/
aleat: rand([1,2]);
ecuaciones:[eqPlano1, eqPlano2]; 
eqPlano: ecuaciones[aleat];

/*Valores PAU
eqPlano: 3*x+m*y-z+1=0;*/

if is(aleat=1) then chk1:chkTrueOk else chk1:true;

ptoRectaEnPlano: solve(subst([x=ptoR[1], y=ptoR[2], z=ptoR[3]], eqPlano))[1];
vecPerpPlano: [coeff(lhs(eqPlano),x), coeff(lhs(eqPlano),y), coeff(lhs(eqPlano),z)];
mParaPerps: solve(vecR.vecPerpPlano=0)[1];

if is(ptoRectaEnPlano=mParaPerps) then tans1:rhs(ptoRectaEnPlano) else tans1: none;

/*Distancia entre dos rectas*/
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];
distRectas(ptoR, vecR, ptoS, vecS):=block(
    vecPtos: ptoS-ptoR,
    productoVectores: prodVect(vecR,vecS),
    modProdVect: sqrt(productoVectores.productoVectores),
    abs(vecPtos.productoVectores)/modProdVect
);

ptoS: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];
vecS: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];

/*Valores PAU
ptoS: [-1,0,-2];
vecS: [2,-1,1];*/

xS1: (x-ptoS[1])/vecS[1];
yS1: (y-ptoS[2])/vecS[2];
zS1: (z-ptoS[3])/vecS[3];

tans2: distRectas(ptoR, vecR, ptoS, vecS);

chk2: is(tans2#0);


ptoT: [rand_with_step(-2,2,1), rand_with_step(-2,2,1), rand_with_step(-2,2,1)];
vecT: [rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0]), rand_with_prohib(-2,2,[0])];

/*Valores PAU
ptoT: [0,0,-2];
vecT: [1,2,2];*/

paramsT: ptoT+t*vecT;
eqParam1T: x=paramsT[1];
eqParam2T: y=paramsT[2];
eqParam3T: z=paramsT[3];
eqImpl1T: simplifica_ec(radcan(eliminate([eqParam1T, eqParam2T],[t])[1]=0));
eqImpl2T: simplifica_ec(radcan(eliminate([eqParam2T, eqParam3T],[t])[1]=0));
eqImpl3T: simplifica_ec(radcan(eliminate([eqParam1T, eqParam3T],[t])[1]=0));
eqsImplT: unique([eqImpl1T, eqImpl2T, eqImpl3T]);

modVecR: sqrt(vecR.vecR);
modVecT: sqrt(vecT.vecT);
cosAngRT: (vecR.vecT)/(modVecR*modVecT);
