planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
planoPerpAVectorPorPto);
eqPlano: planoPerpAVectPorPto(ptoInt, vecPerp);
eqPlano: simplifica_ec(eqPlano);

tans1: ptoInt;

/*Producto vectorial*/
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];
vecAB: ptoB-ptoA;
vecAC: ptoInt-ptoA;
productoVectorial: prodVect(vecAB,vecAC);
moduloProdVect: sqrt(productoVectorial.productoVectorial);

area: moduloProdVect/2;
tans2: area;

/*Comprobación A y B no contenidos en plano*/
chk1: is(subst([x=ptoA[1], y=ptoA[2], z=ptoA[3]], eqPlano));
chk2: is(subst([x=ptoB[1], y=ptoB[2], z=ptoB[3]], eqPlano));
chkTrueOk: not (chk1 or chk2);

/*Simplificación de ecuaciones dividiendo entre mcd de todos los términos*/
simplifica_ec(expr):= block(
eq: lhs(expr)-rhs(expr)=0,
eq: expand(eq),
tnoIndep: subst([x=0,y=0,z=0], lhs(eq)),
coefs: [coeff(lhs(eq),x), coeff(lhs(eq),y), coeff(lhs(eq),z), tnoIndep],
mcd_lista(lista) := block(
    [resultado],
    resultado: first(lista),
    for n in rest(lista) do (
        resultado: gcd(resultado, n)
    ),
    return(resultado)
),
divisor: mcd_lista(coefs),
ecSimplificada: radcan(lhs(eq)/divisor=rhs(eq)/divisor),
return (ecSimplificada)
);

ptoA: [rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
ptoB: [rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
ptoC: [rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0]),rand_with_prohib(-3,3,[0])];
/*Comprobación tres puntos alineados*/
prodVect(x,y):=[x[2]*y[3]-x[3]*y[2], -x[1]*y[3]+x[3]*y[1], x[1]*y[2]-x[2]*y[1]];
estanAlineados(ptoA, ptoB, ptoC):= block(
    prod: prodVect(ptoB-ptoA, ptoC-ptoA),
    is (abs(prod.prod)=0)
    );
chkFalseOk: estanAlineados(ptoA, ptoB, ptoC);
/*Plano por puntos A, B y C*/
ecPlano: radcan(determinant(matrix([x,y,z]-ptoA,ptoB-ptoA,ptoC-ptoA)))=0;
ecPlano: simplifica_ec(ecPlano);
vecPerpPlano: [coeff(lhs(ecPlano),x), coeff(lhs(ecPlano),y), coeff(lhs(ecPlano),z)];
ptoP: ptoB+rand_with_prohib(-3,3,[0])*vecPerpPlano;

/*Valores con que apareció en PAU
ecPlano: 3*x+2*y+z+4=0;
vecPerpPlano: [3,2,1];
ptoP: [1,2,3];
ptoB: [-2,2,0];*/

/*Distancia punto-plano*/
distPtoPlano(pto,plano):=block(
    coefsPlano: [coeff(lhs(plano),x), coeff(lhs(plano),y), coeff(lhs(plano),z)],
    numerador: abs(subst([x=pto[1], y=pto[2], z=pto[3]],lhs(plano))),
    den: sqrt(coefsPlano.coefsPlano),
    numerador/den
);
tans1: distPtoPlano(ptoP,ecPlano);

/*Apdo b simétrico de P respecto del plano*/
simP: ptoP+2*(ptoB-ptoP);

/*Valor PAU
simP: [-5,-2,1];*/

tans2: simP;
tans2x: simP[1];
tans2y: simP[2];
tans2z: simP[3];

/*Plano por P' paralelo a ecPlano*/
/*Plano por punto dado vector perpendicular*/
planoPerpAVectPorPto(pto, vector):= block(
planoPerpAVectorPorPto: vector[1]*x+vector[2]*y+vector[3]*z+DD=0,
aux: solve(subst([x=pto[1], y=pto[2], z=pto[3]],planoPerpAVectorPorPto)),
planoPerpAVectorPorPto: subst(aux, planoPerpAVectorPorPto),
radcan(planoPerpAVectorPorPto));

tans3: planoPerpAVectPorPto(simP, vecPerpPlano);
tans3: simplifica_ec(tans3);
